using System.Collections.Generic;
using System.Linq;

public static class StringCounter
{
    /// <summary>
    /// Counts occurrences of non-empty strings from an enumerable using ordinal case-insensitive comparison.
    /// </summary>
    /// <param name="strings">An IEnumerable of nullable strings.</param>
    /// <returns>A Dictionary mapping normalized string keys to their counts.</returns>
    public static Dictionary<string, int> CountNonEmptyStrings(IEnumerable<string?> strings)
    {
        if (strings == null)
        {
            throw new ArgumentNullException(nameof(strings), "The enumerable cannot be null.");
        }

        return strings
            .Where(s => s != null && !string.IsNullOrEmpty(s))
            .ToDictionary(
                item => item.Trim().ToLowerInvariant(), // Normalize for case-insensitive comparison
                item => CountOccurrences(item, strings) // Note: This logic is slightly flawed in the lambda above as it re-scans. 
                // Correct approach using GroupBy or a single pass accumulator:
            );
