    // Refined version using GroupBy for efficiency and correctness
    public static Dictionary<string, int> CountNonEmptyStrings(IEnumerable<string?> strings)
    {
        if (strings == null)
        {
            throw new ArgumentNullException(nameof(strings), "The enumerable cannot be null.");
        }

        return strings
            .Where(s => s != null && !string.IsNullOrEmpty(s))
            .GroupBy(item => item.Trim().ToLowerInvariant()) // Case-insensitive grouping
            .ToDictionary(group => group.Key, group => group.Count());
    }

    // Usage Example
    public static void Main()
    {
        var input = new List<string?>
        {
            "Hello",
            "HELLO",
            "  HELLO  ",
            null,
            "",
            "World",
            "world"
        };

        var counts = CountNonEmptyStrings(input);

        foreach (var kvp in counts)
        {
            Console.WriteLine($"'{kvp.Key}': {kvp.Value}");
        }
    }
}
